package com.nextrade.persistence.repository; import com.nextrade.persistence.entity.OrderEntity; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Modifying; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.*; import java.time.*; public interface OrderJpaRepository extends JpaRepository<OrderEntity,UUID> { List<OrderEntity> findByInstrumentIdAndStatusInOrderBySequenceAsc(UUID instrumentId,List<String> status); Optional<OrderEntity> findByUserIdAndClientOrderId(UUID userId,String clientOrderId); }